	issuedAt := base.Add(time.Second + 100*time.Millisecond)
	envelope := trust.Envelope{IssuedAt: issuedAt, ExpiresAt: base.Add(4 * time.Second)}
	clock := base.Add(1900 * time.Millisecond)
